#!/usr/bin/env bash
# Duplicate search on bradymholt/cRonstrue: issues and PRs, all states.
# Generated by upstream_scripts.py (QPB v1.6.1 [R]); regenerate rather than edit.
# The operator runs this. A failed search is logged as FAILED and the rest run.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
UPSTREAM=bradymholt/cRonstrue
OUT="$HERE/dup-search.out"
search() {
  local what="$1" query="$2" rc=0
  echo "### gh search $what --repo $UPSTREAM: $query"
  gh search "$what" --repo "$UPSTREAM" --limit 30 -- "$query" || rc=$?
  if [[ $rc -ne 0 ]]; then echo "FAILED: gh search $what (exit $rc)"; fi
  echo
}
{
  echo "# dup-search for $UPSTREAM, $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  echo; echo '## cronstrue-list-step-separator'
  search issues AMonly
  search prs AMonly
  search issues 'stray comma list step'
  search prs 'stray comma list step'
  search issues 'comma-separated values with increments'
  search prs 'comma-separated values with increments'
  search issues 'day of week list range step 5,0-4/2'
  search prs 'day of week list range step 5,0-4/2'
  search issues 'double comma increment multiple values'
  search prs 'double comma increment multiple values'
  search issues 'missing comma after AM'
  search prs 'missing comma after AM'
} > "$OUT" 2>&1
echo "Wrote $OUT. Give it to the agent (paste or upload)."
